def parse_ini(text):
    """Return the sections and key-value pairs in INI text."""
    sections = {}
    section = ""
    key = None

    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.strip()
        if not line or line.startswith(("#", ";")):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            if not section:
                raise ValueError(f"empty section name on line {number}")
            sections.setdefault(section, {})
            key = None
        elif raw.startswith((" ", "\t")):
            if key is None:
                raise ValueError(f"continuation without a key on line {number}")
            sections[section][key] += "\n" + line
        else:
            name, separator, value = line.partition("=")
            if not separator:
                raise ValueError(f"expected an assignment on line {number}")
            key = name.strip().lower()
            if not key:
                raise ValueError(f"empty key on line {number}")
            sections.setdefault(section, {})[key] = value.strip()

    return sections
